import vm from 'node:vm';
import fs from 'node:fs';
import assert from 'node:assert/strict';
const root = '/root/bench-runs/h4-610ab0b5/public/';
const src = fs.readFileSync(root + 'app.js', 'utf8');
const html = fs.readFileSync(root + 'index.html', 'utf8');
for (const bad of ['http://', 'https://', 'innerHTML', 'querySelector', 'createTextNode', 'setAttribute', 'classList', 'console', 'res.ok', '.text()', 'import', 'export', 'encodeURIComponent', 'URLSearchParams'])
  assert(!src.includes(bad), 'app.js has ' + bad);
for (const bad of ['http://', 'https://', '<option', 'Aurora', 'Borealis', 'Cosmos', ' on'])
  assert(!html.includes(bad) || bad === ' on' && !/\son\w+=/.test(html), 'html has ' + bad);
assert(/<script src="\/app.js"><\/script>\s*<\/body>/.test(html));
assert.equal((html.match(/<h1/g) || []).length, 1);

class Node_ {}
class El extends Node_ {
  constructor(tag) { super(); this.tag = tag; this.children = []; this.listeners = {}; this.value = ''; this.disabled = false; this.type = ''; }
  get textContent() { return this.children.map(c => typeof c === 'string' ? c : c.textContent).join(''); }
  set textContent(v) { this.children = v === '' ? [] : [String(v)]; }
  append(...n) { this.children.push(...n); }
  replaceChildren(...n) { this.children = [...n]; }
  addEventListener(t, f) { (this.listeners[t] ||= []).push(f); }
  fire(t, ev = {}) { for (const f of this.listeners[t] || []) f({ preventDefault() { ev.prevented = true; }, ...ev }); return ev; }
}
function setup(fetchImpl) {
  const els = {}; for (const id of ['booking-form','room','title','date','start','end','book','filter-date','show-all','booking-list','error']) els[id] = new El(id);
  const calls = [];
  const ctx = { document: { getElementById: id => els[id], createElement: t => new El(t) }, fetch: (u, o) => { calls.push([u, o]); return fetchImpl(u, o, calls.length); } };
  vm.runInNewContext(src, ctx);
  return { els, calls };
}
const tick = () => new Promise(r => setTimeout(r, 5));
const reply = (status, body, bad) => ({ status, json: () => bad ? Promise.reject(new Error('x')) : Promise.resolve(body) });
const defer = () => { let r; const p = new Promise(x => r = x); return { p, r }; };

// load
let bookings = [{ id: 1, room: 'Aurora', title: '<b>x</b>', date: '2026-11-03', start: '09:00', end: '10:00' }];
let s = setup(u => Promise.resolve(u === '/api/rooms' ? reply(200, { rooms: ['Aurora','Borealis','Cosmos'] }) : reply(200, { bookings })));
assert.deepEqual(s.calls.map(c => c[0]), ['/api/rooms', '/api/bookings']);
await tick();
assert.deepEqual(s.els.room.children.map(o => [o.tag, o.value, o.textContent]), [['option','Aurora','Aurora'],['option','Borealis','Borealis'],['option','Cosmos','Cosmos']]);
const li = s.els['booking-list'].children[0];
assert.equal(li.children.length, 2); assert.equal(li.children[0], '2026-11-03 09:00-10:00 Aurora: <b>x</b>');
assert.equal(li.children[1].type, 'button'); assert.equal(li.children[1].textContent, 'Cancel');
// filter
s.els['filter-date'].value = '2026-11-03'; s.els['filter-date'].fire('input'); assert.equal(s.calls.length, 2);
s.els['filter-date'].fire('change'); assert.equal(s.calls.at(-1)[0], '/api/bookings?date=2026-11-03');
s.els['show-all'].fire('click'); assert.equal(s.els['filter-date'].value, ''); assert.equal(s.calls.at(-1)[0], '/api/bookings');
bookings = []; s.els['filter-date'].fire('change'); await tick();
assert.equal(s.els['booking-list'].children.length, 1); assert.deepEqual(s.els['booking-list'].children[0].children, ['No bookings.']);

// rooms error / no reply / json reject
s = setup(u => u === '/api/rooms' ? Promise.resolve(reply(500, { error: 'internal error' })) : new Promise(() => {}));
await tick(); assert.equal(s.els.error.textContent, 'internal error'); assert.equal(s.els.room.children.length, 0);
s = setup(u => u === '/api/rooms' ? Promise.resolve(reply(500, [1])) : new Promise(() => {}));
await tick(); assert.equal(s.els.error.textContent, 'Request failed.');
s = setup(u => u === '/api/rooms' ? Promise.resolve(reply(200, null, true)) : new Promise(() => {}));
await tick(); assert.equal(s.els.error.textContent, 'Could not reach the server.');
s = setup(u => u === '/api/rooms' ? Promise.reject(new TypeError('x')) : new Promise(() => {}));
await tick(); assert.equal(s.els.error.textContent, 'Could not reach the server.');

// stale list fetch
const d1 = defer(), d2 = defer();
s = setup((u, o, n) => u === '/api/rooms' ? new Promise(() => {}) : (n === 2 ? d1.p : d2.p));
s.els['filter-date'].fire('change');
d2.r(reply(200, { bookings: [] })); await tick();
d1.r(reply(400, { error: 'stale' })); await tick();
assert.equal(s.els.error.textContent, ''); assert.deepEqual(s.els['booking-list'].children[0].children, ['No bookings.']);

// booking
let postReply = defer();
s = setup((u, o) => u === '/api/bookings' && o.method === 'POST' ? postReply.p : u === '/api/rooms' ? Promise.resolve(reply(200, { rooms: ['Aurora'] })) : Promise.resolve(reply(200, { bookings: [] })));
await tick();
Object.assign(s.els.title, { value: ' T ' }); s.els.date.value = '2026-11-03'; s.els.start.value = '09:00'; s.els.end.value = '10:00'; s.els.room.value = 'Aurora';
s.els.error.textContent = 'old';
let ev = s.els['booking-form'].fire('submit'); assert(ev.prevented);
assert.equal(s.els.book.disabled, true);
const [u, o] = s.calls.at(-1);
assert.equal(u, '/api/bookings'); assert.deepEqual(o.headers, { 'Content-Type': 'application/json' });
assert.deepEqual(JSON.parse(o.body), { room: 'Aurora', title: ' T ', date: '2026-11-03', start: '09:00', end: '10:00' });
const n = s.calls.length; ev = s.els['booking-form'].fire('submit'); assert(ev.prevented); assert.equal(s.calls.length, n);
postReply.r(reply(201, { id: 1 })); await tick();
assert.equal(s.els.book.disabled, false); assert.equal(s.els.title.value, ''); assert.equal(s.els.error.textContent, ''); assert.equal(s.calls.at(-1)[0], '/api/bookings'); assert.equal(s.calls.length, n + 1);
postReply = defer(); s.els.title.value = 'X'; s.els['booking-form'].fire('submit');
postReply.r(reply(409, { error: 'room is already booked from 09:00 to 10:00' })); await tick();
assert.equal(s.els.error.textContent, 'room is already booked from 09:00 to 10:00'); assert.equal(s.els.title.value, 'X'); assert.equal(s.calls.length, n + 2);
postReply = defer(); s.els['booking-form'].fire('submit'); postReply.r(reply(201, null, true)); await tick();
assert.equal(s.els.error.textContent, 'Could not reach the server.'); assert.equal(s.els.book.disabled, false); assert.equal(s.els.title.value, 'X');

// cancel
let del = defer(); let readBody = false;
s = setup((u, o) => o.method === 'DELETE' ? del.p : u === '/api/rooms' ? Promise.resolve(reply(200, { rooms: [] })) : Promise.resolve(reply(200, { bookings: [{ id: 7, room: 'Cosmos', title: 't', date: '2026-01-01', start: '01:00', end: '02:00' }] })));
await tick();
let btn = s.els['booking-list'].children[0].children[1];
btn.fire('click'); assert.equal(btn.disabled, true); assert.equal(s.calls.at(-1)[0], '/api/bookings/7'); assert.equal(s.calls.at(-1)[1].method, 'DELETE');
s.els.error.textContent = 'old';
del.r({ status: 204, json() { readBody = true; return Promise.reject(new Error()); } }); await tick();
assert(!readBody); assert.equal(btn.disabled, false); assert.equal(s.els.error.textContent, ''); assert.equal(s.calls.at(-1)[0], '/api/bookings');
const m = s.calls.length;
btn = s.els['booking-list'].children[0].children[1]; del = defer(); btn.fire('click'); del.r(reply(404, { error: 'booking not found' })); await tick();
assert.equal(s.els.error.textContent, 'booking not found'); assert.equal(s.calls.length, m + 2);
btn = s.els['booking-list'].children[0].children[1]; del = defer(); btn.fire('click'); del.r(Promise.reject(new TypeError())); await tick();
assert.equal(s.els.error.textContent, 'Could not reach the server.'); assert.equal(s.calls.length, m + 3); assert.equal(btn.disabled, false);
console.log('ALL OK');
